'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { isValidElement, type ComponentProps, type ReactNode } from 'react';
import { Button as AriaButton, Link as AriaLink, Focusable, TooltipTrigger, Tooltip as AriaTooltip, OverlayArrow, type TooltipProps as AriaTooltipProps } from 'react-aria-components';
import { IconButton } from '@/components/base/buttons/icon-button';
import { cx } from '@/utils/cx';

export type TooltipProps = { children: ComponentProps<typeof Focusable>['children']; content: ReactNode; placement?: AriaTooltipProps['placement']; delay?: number; closeDelay?: number; showArrow?: boolean; isDisabled?: boolean; className?: string; /** Aria triggers already consume TooltipTrigger's public focus context. */ triggerType?:'auto'|'native'|'aria' };
export function Tooltip({ children, content, placement = 'top', delay = 350, closeDelay = 100, showArrow = true, isDisabled, className, triggerType='auto' }: TooltipProps) {
  const childDisabled = isValidElement<{disabled?: boolean;isDisabled?: boolean}>(children) && (children.props.disabled || children.props.isDisabled);
  const disabled = isDisabled ?? Boolean(childDisabled);
  const triggerComponent:unknown=isValidElement(children)?children.type:null;
  const ariaTrigger=triggerType==='aria'||triggerType==='auto'&&isValidElement(children)&&[IconButton,AriaButton,AriaLink].some(type=>triggerComponent===type);
  return <TooltipTrigger delay={delay} closeDelay={closeDelay} isDisabled={disabled}>{ariaTrigger?children:<Focusable isDisabled={disabled}>{children}</Focusable>}<AriaTooltip placement={placement} offset={7} className={cx('ui-tooltip', className)}>{showArrow && <OverlayArrow className="ui-tooltip__arrow"><svg width="10" height="6" viewBox="0 0 10 6" aria-hidden="true"><path d="M0 0 5 5 10 0" /></svg></OverlayArrow>}{content}</AriaTooltip></TooltipTrigger>;
}

'use client';

import { useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { RiArrowDownLine } from '@remixicon/react';
import { animate } from 'motion/react';
import { IconButton } from '@/components/base/buttons/icon-button';
import { Tooltip } from '@/components/base/tooltip/tooltip';
import { useMediaQuery } from '@/hooks/use-media-query';
import { useMotionTokens } from '@/hooks/use-motion-tokens';
import { cx } from '@/utils/cx';

export type ConversationProps = {
  children: ReactNode;
  label?: string;
  conversationKey?: string;
  isStreaming?: boolean;
  autoScroll?: boolean;
  initialScroll?: 'start'|'end';
  height?: CSSProperties['height'];
  footer?: ReactNode;
  header?: ReactNode;
  className?: string;
  contentClassName?: string;
};

/** Follow new content while at the end; preserve a reader's position above it. */
export function Conversation({children,label='Conversation',conversationKey,isStreaming=false,autoScroll=true,initialScroll='end',height,header,footer,className,contentClassName}: ConversationProps) {
  const viewport=useRef<HTMLDivElement>(null),content=useRef<HTMLDivElement>(null),following=useRef(initialScroll==='end'),jumping=useRef(false),lastTop=useRef(0),manualIntent=useRef(false),touchStart=useRef<number|null>(null),scrollAnimation=useRef<{stop():void}|null>(null),scrollTarget=useRef<'start'|'end'|null>(null),scrollGeneration=useRef(0),scrollToLatest=useRef<(target:'start'|'end')=>void>(()=>{});
  const [atEnd,setAtEnd]=useState(true),reduced=useMediaQuery('(prefers-reduced-motion: reduce)'),motion=useMotionTokens(viewport);
  function measurePosition(fromScroll=false){const el=viewport.current;if(!el)return;const near=el.scrollHeight-el.clientHeight-el.scrollTop<=32;if(!jumping.current){if(manualIntent.current){if(fromScroll&&!near){manualIntent.current=false;following.current=false;}}else if(near)following.current=true;else if(fromScroll&&el.scrollTop<lastTop.current-.5)following.current=false;}lastTop.current=el.scrollTop;setAtEnd(near);}
  useLayoutEffect(()=>{
    const el=viewport.current,body=content.current;if(!el||!body)return;
    interrupt();manualIntent.current=false;touchStart.current=null;lastTop.current=0;
    following.current=initialScroll==='end';
    el.scrollTop=initialScroll==='end'?el.scrollHeight:0;measurePosition();
    const observer=new ResizeObserver(()=>{if(scrollTarget.current==='end'){scrollToLatest.current('end');}else if(autoScroll&&following.current){el.scrollTop=el.scrollHeight;}measurePosition();});
    observer.observe(el);observer.observe(body);
    return()=>{observer.disconnect();interrupt();};
  },[conversationKey,autoScroll,initialScroll]);
  function interrupt(){scrollGeneration.current++;scrollAnimation.current?.stop();scrollAnimation.current=null;scrollTarget.current=null;jumping.current=false;}
  function scrollTo(target:'start'|'end'){
    const el=viewport.current;if(!el)return;
    interrupt();const generation=scrollGeneration.current;
    scrollTarget.current=target;jumping.current=true;manualIntent.current=target==='start';following.current=target==='end';
    const top=target==='end'?Math.max(0,el.scrollHeight-el.clientHeight):0;
    function complete(){if(scrollGeneration.current!==generation)return;scrollAnimation.current=null;scrollTarget.current=null;jumping.current=false;measurePosition();}
    if(reduced||Math.abs(el.scrollTop-top)<.5){el.scrollTop=top;complete();return;}
    scrollAnimation.current=animate(el.scrollTop,top,{duration:motion.standard,ease:motion.ease,onUpdate:value=>{el.scrollTop=value;},onComplete:complete});
  }
  function jump(){viewport.current?.focus({preventScroll:true});scrollTo('end');}
  scrollToLatest.current=scrollTo;
  return <section className={cx('ui-conversation',className)} aria-label={label} style={height?{height}:undefined}>
    {header && <header className="ui-conversation__header">{header}</header>}
    <div className="ui-conversation__body">
    <div ref={viewport} className="ui-conversation__viewport" tabIndex={0} role="log" aria-label={`${label} messages`} aria-live="polite" aria-relevant="additions" aria-atomic="false" aria-busy={isStreaming || undefined} onScroll={()=>measurePosition(true)} onWheel={event=>{manualIntent.current=event.deltaY<0;if(event.deltaY<0)following.current=false;interrupt();}} onTouchStart={event=>{touchStart.current=event.touches[0]?.clientY??null;interrupt();}} onTouchMove={event=>{if(touchStart.current!==null){manualIntent.current=(event.touches[0]?.clientY??touchStart.current)>touchStart.current;if(manualIntent.current)following.current=false;}}} onTouchEnd={()=>{touchStart.current=null;}} onTouchCancel={()=>{touchStart.current=null;}} onPointerDown={interrupt} onKeyDown={event=>{if(event.defaultPrevented||(event.target as HTMLElement).closest('input,textarea,[contenteditable="true"]'))return;if((event.key==='Home'||event.key==='End')&&event.target===viewport.current){event.preventDefault();scrollTo(event.key==='End'?'end':'start');return;}if(event.key==='End'){manualIntent.current=false;following.current=true;}if(['ArrowUp','PageUp','Home'].includes(event.key)||event.key===' '&&event.shiftKey){manualIntent.current=true;following.current=false;}else if(['ArrowDown','PageDown',' '].includes(event.key))manualIntent.current=false;if(['ArrowUp','ArrowDown','PageUp','PageDown','Home','End',' '].includes(event.key))interrupt();}}>
      <div ref={content} className={cx('ui-conversation__content',contentClassName)}>{children}</div>
    </div>
    {!atEnd && <div className="ui-conversation__jump"><Tooltip content="Jump to latest message"><IconButton icon={RiArrowDownLine} size="small" aria-label="Jump to latest message" onClick={jump}/></Tooltip></div>}
    </div>
    {footer && <div className="ui-conversation__footer">{footer}</div>}
  </section>;
}

'use client';

import { useCallback, useSyncExternalStore } from 'react';

export function useMediaQuery(query: string) {
  const subscribe = useCallback((notify: () => void) => {
    const media = window.matchMedia(query);
    media.addEventListener('change', notify);
    return () => media.removeEventListener('change', notify);
  }, [query]);
  const snapshot = useCallback(() => window.matchMedia(query).matches, [query]);
  return useSyncExternalStore(subscribe, snapshot, () => false);
}

// Keep these in sync with the navigation and inspector media queries in template CSS.
export const TEMPLATE_NAV_QUERY = '(max-width: 1023px)';
export const TEMPLATE_PANEL_QUERY = '(max-width: 1279px)';

'use client';

import {useLayoutEffect,useState,type RefObject} from 'react';

export type MotionTokens={fast:number;standard:number;settle:number;ease:[number,number,number,number]};
const defaults:MotionTokens={fast:.16,standard:.24,settle:.36,ease:[.2,.75,.25,1]};
function seconds(value:string,fallback:number){const match=value.trim().match(/^([\d.]+)(ms|s)$/);if(!match)return fallback;const amount=Number(match[1])/(match[2]==='ms'?1000:1);return Number.isFinite(amount)&&amount>=0?amount:fallback;}

/** Use the same scoped CSS tokens for JavaScript layout/glyph animation. */
export function useMotionTokens(scope?:RefObject<Element|null>){
  const [tokens,setTokens]=useState<MotionTokens>(defaults);
  useLayoutEffect(()=>{
    const element=scope?.current??document.documentElement;
    function read(){
      const style=getComputedStyle(element),curve=style.getPropertyValue('--motion-ease').match(/^\s*cubic-bezier\(([^)]+)\)/)?.[1].split(',').map(Number);
      const ease=curve?.length===4&&curve.every(Number.isFinite)?curve as MotionTokens['ease']:defaults.ease;
      const next={fast:seconds(style.getPropertyValue('--motion-fast'),defaults.fast),standard:seconds(style.getPropertyValue('--motion-standard'),defaults.standard),settle:seconds(style.getPropertyValue('--motion-settle'),defaults.settle),ease};
      setTokens(current=>current.fast===next.fast&&current.standard===next.standard&&current.settle===next.settle&&current.ease.every((value,index)=>value===next.ease[index])?current:next);
    }
    read();const observer=new MutationObserver(read);
    observer.observe(document.documentElement,{attributes:true,attributeFilter:['style','class','data-accent']});
    if(element!==document.documentElement)observer.observe(element,{attributes:true,attributeFilter:['style','class']});
    return()=>observer.disconnect();
  },[scope]);
  return tokens;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
